    "curated": true,
    "status": "draft",
    "editorialReference": 41,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>You can explore changing your MTD accountant during the year, but a good handover matters more than the date you move. The incoming accountant needs to understand both the records and the work already submitted.</p>\n<h2>Start with a clear handover list</h2>\n<p>Ask your current accountant for the digital records, submission history, reporting periods and any outstanding queries. Request an explanation of how you can export or retain access to the records. Access to an HMRC account alone is not a replacement for the bookkeeping behind it.</p>\n<p>HMRC supports different agent roles for MTD. The relevant authorisations must match the work your new accountant is taking over. Do not assume that ending a commercial arrangement automatically updates every permission.</p>\n<h2>Agree who owns the next deadline</h2>\n<p>Before transferring, write down which firm will complete the next update and which will prepare the annual return. Avoid an arrangement where each believes the other is filing. Tell the incoming accountant about any previous corrections or incomplete periods.</p>\n<p>TaxSimba asks which quarters have already been submitted so the assigned accountant can review the starting position. A client-declared previous submission is different from work filed by TaxSimba.</p>\n<h2>Check the commercial arrangements</h2>\n<p>Ask about notice requirements, unpaid fees and any charge for reviewing earlier work. If corrections are needed, agree the scope and price before authorising them.</p>\n<h2>Example: moving after the second update</h2>\n<p>If the first two updates have been filed, the new accountant still needs the records from the start of the tax year. The third update is cumulative, so starting with only the latest three months can leave the new firm without a complete picture.</p>\n<h2>Can two accountants both be involved?</h2>\n<p>Different agent arrangements can be possible, but responsibilities need to be explicit. Name who maintains the records, who sends the next update and who finalises the annual return. Avoid asking both firms to submit the same work.</p>\n<h2>Will switching correct old errors automatically?</h2>\n<p>No. A handover transfers information and responsibilities. Reviewing or correcting earlier work is a separate question. Ask the incoming accountant to identify any concerns, explain the proposed work and confirm any extra fee before it starts.</p>\n<p><strong>Next step:</strong> Contact TaxSimba with your current reporting periods, submitted updates and available records so the handover can be assessed before you commit.</p>",
