    "editorialReference": 56,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>A job and a self-employed activity can belong in the same individual tax return. The accountant needs both sets of information to assess the complete position rather than treating the side business in isolation.</p>\n<h2>Bring the employment evidence</h2>\n<p>Gather your P60 or relevant P45, any taxable-benefit information and details of other jobs during the year. Explain job changes and any figures you believe are incorrect. PAYE deductions matter when the overall calculation is prepared.</p>\n<h2>Bring the business evidence separately</h2>\n<p>Provide income records, allowable-expense documents and the dates you started or stopped trading. Distinguish money earned from customers from transfers out of your salary account. Paying business costs from personal funds does not make the transactions disappear.</p>\n<p>Use the correct tax year for both sets of documents. A calendar-year platform summary may need reconciling to the UK tax-year records.</p>\n<h2>Do you definitely need to file?</h2>\n<p>Use HMRC’s current checker rather than assuming every small amount of extra income requires the same action. Equally, do not ignore a notice to file just because tax has already been deducted from your salary.</p>\n<h2>What to ask before purchasing</h2>\n<p>Confirm that the service covers employment and self-employment together. Tell the accountant about other income, loans, pension contributions or property so these are not discovered after the scope is agreed.</p>\n<h2>Example: wages and freelance receipts</h2>\n<p>Keep your employment income and PAYE evidence separate from freelance sales and expenses. The return brings the relevant information together, but the bookkeeping should still explain where each figure came from.</p>\n<h2>Do I get another Personal Allowance for the business?</h2>\n<p>Do not assume each income source has its own separate allowance. Your accountant considers the individual’s overall position and the rules for the year. That is one reason the employment information matters even when your question concerns only the side business.</p>\n<h2>What if my employer already knows about the side work?</h2>\n<p>An employer knowing about it does not replace your tax-reporting responsibilities. Likewise, a business platform reporting information to HMRC is not the same as completing your return. Check the filing requirement and keep your own records.</p>\n<p><strong>Next step:</strong> Share both your employment documents and business records through TaxSimba’s document process for the tax year purchased.</p>",
    "editorialStatus": "final-copy",
    "wordCount": 365,
    "targetQuery": "employed and self employed tax return",
