    "status": "draft",
    "editorialReference": 57,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>For a self-employed private-hire driver, the amount paid into the bank may not tell the full story. Platform deductions and different payment methods can make a tax return harder to prepare from bank statements alone.</p>\n<h2>Start with the full earnings breakdown</h2>\n<p>Download your platform statements for the relevant tax year. Keep records of fares, adjustments, fees and cash receipts where applicable. If you drive through several platforms or take other bookings, include those records too.</p>\n<p>Ask the accountant to reconcile the platform totals to the bank deposits. Do not record a net payout as the full sales figure and then deduct the same platform fees again.</p>\n<h2>Keep vehicle evidence consistent</h2>\n<p>Provide mileage records and vehicle invoices or agreements. There are different ways to deal with business vehicle costs, and previous claims can affect the available method. Do not assume that fuel receipts and a mileage deduction can simply be added together.</p>\n<p>Other costs need a genuine business connection and supporting evidence. Explain private use rather than labelling every payment as a driver expense.</p>\n<h2>Agree the scope</h2>\n<p>Employment status and working arrangements matter. Describe how you operate before assuming a particular tax treatment. Tell the accountant if you also have a job or another trade.</p>\n<h2>A practical year-end folder</h2>\n<p>Keep one set of platform summaries, one set of vehicle documents and one list of other business costs. Add explanations for transfers, refunds and unusual adjustments. Label every document with the period it covers.</p>\n<h2>Can I claim all vehicle spending?</h2>\n<p>Not automatically. The method used, business use, prior claims and the nature of each cost matter. Do not combine a mileage claim with the same running costs again without the accountant checking the treatment.</p>\n<h2>Does this guide cover every driver’s employment status?</h2>\n<p>No. Passenger transport can involve different arrangements. Describe who pays you, how bookings are accepted and the contractual position. If you are employed as well as driving independently, provide the employment documents too. The accountant needs the facts before selecting the return treatment.</p>\n<p><strong>Next step:</strong> Gather platform statements, vehicle information and a sample of your records before choosing TaxSimba’s SA service. This helps the accountant identify missing information early.</p>",
