    "editorialReference": 58,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>Working across delivery apps can leave your tax information scattered between weekly statements, cash records and bank deposits. Organising it by platform is a useful first step towards a complete return.</p>\n<h2>Reconcile each app separately</h2>\n<p>Download the available earnings statements and keep details of fees, adjustments and any other amounts received through the work. Record the dates covered. Then match the statements to the money paid into your account.</p>\n<p>Do not assume a platform reporting information to HMRC means your own tax obligations have been completed. Reporting by a platform and submitting an individual tax return are different processes.</p>\n<h2>Give the accountant the vehicle facts</h2>\n<p>Explain whether you use a bicycle, motorcycle, car or van, and whether it is also used privately. Keep relevant purchase or lease documents and mileage evidence where appropriate. The correct treatment depends on the circumstances and the method used.</p>\n<p>Keep phone bills, insurance documents and other work-related receipts available for review. A payment is not deductible simply because it happened during a shift.</p>\n<h2>Include work outside the apps</h2>\n<p>Tell the accountant about another job, direct customers or other self-employed activities. Avoid sending only the platform with the highest earnings.</p>\n<h2>Example: two apps and direct work</h2>\n<p>A courier using two platforms plus occasional direct bookings should retain all three income records. A single annual summary from the busiest app is not a complete record of the activity.</p>\n<h2>Are platform payments already taxed?</h2>\n<p>Do not assume so from the fact that money arrived after deductions. Some deductions are platform charges rather than Income Tax. Use the statement to identify what was actually withheld and give it to the accountant.</p>\n<h2>What if I changed vehicle during the year?</h2>\n<p>Record when each vehicle was used and retain the relevant costs and mileage evidence. Explain any private use. Switching vehicles should not result in combining all the costs and applying one unexplained business percentage to everything.</p>\n<p><strong>Next step:</strong> Create one folder for each platform and the tax year, then share the statements and expense evidence with TaxSimba. The accountant can check the complete picture before preparing the return.</p>",
