    "curated": true,
    "status": "draft",
    "editorialReference": 59,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>Salon work can involve employment, self-employment or a mixture of arrangements. Before preparing a tax return, make sure the accountant understands how you actually work.</p>\n<h2>Explain the working arrangement</h2>\n<p>Describe whether you rent a chair or room, set your own prices, take bookings directly and buy your own supplies. A contract label alone does not settle employment status. HMRC has specific guidance for people working in hair and beauty.</p>\n<p>If you are employed by a salon and see private clients separately, give the accountant both sets of records. Keep employment documents separate from the business takings.</p>\n<h2>Capture every payment method</h2>\n<p>Maintain a consistent record of cash, card and bank payments. Include booking-platform summaries and relevant deductions so the accountant can reconcile the totals. Mark transfers and personal contributions clearly.</p>\n<h2>Keep expense evidence useful</h2>\n<p>Organise supply invoices, chair or room-rental statements and other business costs. Explain mixed use of a phone or workspace. Ordinary personal spending should not be relabelled as business spending just because appearance matters in the industry.</p>\n<p>Make a note of cancelled appointments, refunds and adjustments rather than changing totals without explanation. The trail should help someone else understand the figures.</p>\n<h2>Example: salon employment and private clients</h2>\n<p>A person employed for part of the week may also operate a separate mobile service. The accountant needs the employment documents and private-client records. Do not mix the salary with cash takings and describe the whole amount as salon turnover.</p>\n<h2>Are cash tips and card receipts irrelevant if they are small?</h2>\n<p>Give the accountant the complete payment information rather than excluding amounts yourself. Explain what the receipts relate to so the correct treatment can be assessed.</p>\n<h2>Are ordinary clothes and grooming automatically business expenses?</h2>\n<p>No. Personal appearance being important to the work does not make every related cost deductible. Organise protective clothing, uniforms and other specific costs for review, keeping personal spending separate. Ask about the actual item and use instead of relying on a broad industry expense list.</p>\n<p><strong>Next step:</strong> Tell TaxSimba how your salon or mobile service operates and provide a sample of your records. The accountant can then confirm what information is needed and whether the selected service is suitable.</p>",
    "editorialStatus": "final-copy",
    "wordCount": 362,
    "targetQuery": "self employed beautician tax return",
    "priority": "P2",
    "differentiation": "Industry-specific employment-status and mixed-payment records.",
