    "curated": true,
    "status": "draft",
    "editorialReference": 61,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>Selling unwanted clothes is not automatically the same as running a resale business. The activity behind the sales matters more than a social-media headline about a fixed number of listings.</p>\n<h2>Separate a clear-out from trading</h2>\n<p>Describe why you bought the items and what you do now. Selling your own used belongings can be different from regularly buying stock to resell at a profit. If your activity has changed over time, keep the dates clear.</p>\n<p>HMRC’s platform guidance says reporting your details does not automatically mean you owe tax. Equally, a lack of a reporting notification does not prove that trading income is outside tax.</p>\n<h2>Keep evidence before you need it</h2>\n<p>Save sales summaries, purchase information and explanations of unusual transactions. If you are trading, keep records of associated costs and refunds as well as payouts. Do not delete transaction history simply because an account has closed.</p>\n<p>Avoid treating a platform’s reporting threshold as a personal tax allowance. These are different rules and answer different questions.</p>\n<h2>Ask about valuable items separately</h2>\n<p>The tax treatment of a valuable possession may need a different review from ordinary trading income. Tell the accountant about high-value sales rather than assuming every personal item is automatically irrelevant.</p>\n<h2>Example: clearing a wardrobe versus buying stock</h2>\n<p>Selling clothes you originally bought for yourself is different from regularly sourcing items to resell. Keep enough information to explain the activity, especially if a platform statement shows a large number of transactions.</p>\n<h2>Is the platform’s reporting threshold a tax allowance?</h2>\n<p>No. Information-reporting rules and the rules for deciding taxable income serve different purposes. Do not conclude that a particular number of sales automatically makes every receipt taxable, or that staying below a platform-reporting threshold means a business is exempt.</p>\n<h2>What if I do both activities?</h2>\n<p>Separate the records of personal-item sales and trading stock, with purchase information where available. Give the accountant an explanation of each rather than subtracting an estimated personal amount from the final bank payouts.</p>\n<p><strong>Next step:</strong> Use HMRC’s online-income checker. If the activity looks like a business or you are unsure, explain the buying and selling pattern to TaxSimba before deciding whether a return is needed.</p>",
    "editorialStatus": "final-copy",
    "wordCount": 359,
    "targetQuery": "Vinted tax selling personal items",
