    "sources": [
      {
        "label": "GOV.UK — selling goods or services on a digital platform",
        "url": "https://www.gov.uk/guidance/selling-goods-or-services-on-a-digital-platform"
      },
      {
        "label": "GOV.UK — what records to keep",
        "url": "https://www.gov.uk/self-employed-records/what-records-to-keep"
      },
      {
        "label": "GOV.UK — simpler income tax cash basis",
        "url": "https://www.gov.uk/simpler-income-tax-cash-basis"
      }
    ],
    "curated": true,
    "status": "draft",
    "editorialReference": 62,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>An Etsy payout can combine sales, fees, refunds and adjustments. Preparing a tax return from the final bank deposit alone can make it difficult to understand what the shop earned and spent.</p>\n<h2>Download the shop statements</h2>\n<p>Keep transaction exports and relevant payment reports for the tax year. Record which periods they cover and retain supporting invoices. If your shop also sells elsewhere, give the accountant those records rather than assuming one marketplace report covers the whole business.</p>\n<h2>Reconcile before calculating profit</h2>\n<p>Ask how the sales figures relate to the payout. Fees deducted before the money reaches your bank need identifying, but should not be deducted again if they have already been accounted for in the figures used.</p>\n<p>Refunds and cancelled orders need a clear trail. Keep a note when an adjustment relates to an earlier transaction so it can be considered correctly.</p>\n<h2>Organise costs by business purpose</h2>\n<p>Keep evidence for materials, packaging, postage and other shop-related spending. Explain any mixed personal use. The accounting treatment depends on your circumstances and method, not simply the name of the retailer on a receipt.</p>\n<p>Platform reporting to HMRC does not replace your responsibility to establish the correct figures and filing position.</p>\n<h2>Example: the payout reconciliation</h2>\n<p>A shop may receive customer payments, issue refunds and have fees deducted before the remaining money reaches the bank. Keep a schedule linking those components. Do not treat the final payout and original sales as two separate sets of income.</p>\n<h2>What if statements use a calendar year?</h2>\n<p>Tell the accountant what period the export covers. UK tax-year preparation may need a different cut-off, so an annual platform report should not be copied into the return without checking its dates.</p>\n<h2>Do platform reports mean I no longer need my own records?</h2>\n<p>No. Your accountant still needs evidence to assess the correct figures and expenses. Download exports and invoices while access is available, and retain explanations for changes such as a shop closure or migration to another sales platform.</p>\n<p><strong>Next step:</strong> Give TaxSimba your marketplace exports, bank statements and cost records together. This is more useful than sending only the amount withdrawn from the platform.</p>",
    "editorialStatus": "final-copy",
    "wordCount": 355,
    "targetQuery": "Etsy seller tax return UK",
    "priority": "P2",
    "differentiation": "Marketplace fee reconciliation and refunds.",
