    "editorialReference": 74,
    "researchCheckedAt": "2026-10-20",
    "content": "<p>Pension contributions can affect a tax calculation, but the accountant needs to know how the contributions were made. A total described simply as “my pension payments” may not be enough.</p>\n<h2>Identify the contribution method</h2>\n<p>Gather pension statements and relevant payslips. Explain whether contributions came from pay, were paid personally or involved salary sacrifice. Different tax-relief methods mean the same-looking payment should not automatically be entered in the same place.</p>\n<p>HMRC’s guidance explains the treatment of relief-at-source contributions and claims for additional relief. Avoid claiming relief twice where it has already been given through another mechanism.</p>\n<h2>Explain the wider income picture</h2>\n<p>Adjusted net income can matter for the Personal Allowance and other income-related rules. The accountant needs the relevant income and contribution details, not only your headline salary.</p>\n<p>Timing is important. Identify the date contributions were paid and the tax year concerned. Do not assume a payment made now can retrospectively fix the previous year’s position.</p>\n<h2>Get advice before making a large payment</h2>\n<p>Tax treatment, contribution limits and the suitability of a pension decision need their own review. A tax-return article is not a recommendation to invest or transfer money.</p>\n<h2>Example: a personal contribution statement</h2>\n<p>If you made a payment personally, provide the statement showing the contribution and any tax relief added by the provider. Do not enter the same contribution again as though it were a separate payroll deduction.</p>\n<h2>Can I claim additional relief automatically?</h2>\n<p>The answer depends on the contribution method, income and relevant limits. Basic-rate relief already added by a provider does not settle every higher-rate claim, but it must be accounted for to avoid duplication.</p>\n<h2>Can I backdate a contribution by changing the description?</h2>\n<p>No. Give the accountant the actual payment dates. Ask about the rules before making decisions; allowances or carry-forward concepts do not mean a new payment can simply be described as paid in an earlier tax year.</p>\n<p><strong>Next step:</strong> Send TaxSimba the pension documents and explain what you want checked. The accountant can review the tax-return treatment within the agreed scope and identify where separate specialist advice is needed.</p>",
    "editorialStatus": "final-copy",
    "wordCount": 345,
    "targetQuery": "pension contributions adjusted net income tax return",
    "priority": "P2",
    "differentiation": "Evidence and relief mechanism; not personal investment advice.",
