    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>MTD allows a main agent and supporting agents to help with different tasks. The distinction matters if one person keeps your books and another prepares your annual tax return. Agree who does what before authorising a new accountant.</p>\n<h2>What a main agent does</h2>\n<p>A main agent can manage the overall MTD tax position and submit the annual return. HMRC allows only one main agent at a time. Replacing that authorisation can affect the accountant who was previously responsible, so tell both providers about a planned change.</p>\n<h2>What a supporting agent does</h2>\n<p>A supporting agent can help with tasks such as digital records and quarterly updates, but cannot submit the annual MTD Income Tax return as your main agent. There can be more than one supporting agent, and their access is more limited.</p>\n<p>Having someone authorised for quarterly work therefore does not establish that the annual return is covered. Check the engagement, the HMRC authorisation and the practical handover arrangements together.</p>\n<h2>Avoid two people filing overlapping figures</h2>\n<p>If several people work on the same business, HMRC requires one combined update for each update period. A bookkeeper should not send one version while an accountant independently sends another incomplete version of the same business totals.</p>\n<p>For example, you might maintain sales records while a supporting bookkeeper records expenses. Someone must reconcile the whole record before the agreed agent submits the update. Access to software is not a substitute for agreeing that responsibility.</p>\n<h2>Questions to settle in writing</h2>\n<p>Identify who maintains records, who sends updates, who deals with corrections, who gathers other personal income and who prepares the annual return. Confirm how records and submission evidence will pass between the people involved.</p>\n<p>When joining TaxSimba, disclose any existing accountant or bookkeeper and their current role. TaxSimba can then confirm the authorisation and work required for your agreed service. You should retain your own Government Gateway credentials; authorised agent access should not depend on giving another person your password or security codes.</p>",
    "wordCount": 328,
    "iconKey": "digital-tax",
    "contentType": "Answer guide",
    "readingMinutes": 2,
