    "curated": true,
    "status": "draft",
    "editorialReference": 93,
    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>Your Self Assessment bill may include National Insurance as well as Income Tax. For a 2025/26 sole trader return, use that year&#x27;s thresholds rather than copying the figures currently displayed for 2026/27.</p>\n<h2>Class 4 is based on taxable trading profits</h2>\n<p>For 2025/26, Class 4 is generally 6% on profits over £12,570 up to £50,270, and 2% above £50,270. Other rules can affect the calculation, including age and interaction with employment contributions.</p>\n<p>Turnover and profit are different. A trader with £40,000 of sales does not normally calculate Class 4 on the full £40,000 if allowable business costs reduce the taxable profit.</p>\n<h2>Class 2 does not always mean a separate charge</h2>\n<p>For 2025/26, qualifying self-employed profits of £6,845 or more generally mean Class 2 is treated as paid to protect the National Insurance record, without a Class 2 payment. Below that level, voluntary Class 2 may be available at £3.50 a week, subject to the relevant conditions.</p>\n<p>Do not assume that a voluntary payment is beneficial merely because the option appears. Check your contribution record, existing credits and eligibility before deciding whether to pay. Equally, do not assume that low profit automatically gives you a qualifying year.</p>\n<h2>Tell the accountant about employment too</h2>\n<p>If you were employed and self-employed in the same year, provide your P60 and trading records. Employment contributions and self-employed contributions interact under rules that a simple single-income estimate may not capture.</p>\n<p>Ordinary residential rental income is not automatically subject to the same National Insurance treatment as a sole trade. Explain what you actually do rather than describing every income source as self-employment.</p>\n<h2>Check the components before paying</h2>\n<p>Ask how much of the bill is Income Tax, Class 4 and any voluntary Class 2. Payments on account can also make the amount due differ from the year&#x27;s liability.</p>\n<p>TaxSimba can prepare the return using the relevant year and your full income information. Keep National Insurance questions separate from the monthly fee paid for an MTD accounting service; one is a government liability and the other pays for professional work.</p>",
    "wordCount": 355,
