    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>A personal trainer can be employed by a gym, self-employed, or have a mixture of arrangements. Your tax records should reflect the actual contracts and income sources rather than assuming every fitness payment is treated alike.</p>\n<h2>Identify who pays you and why</h2>\n<p>Keep gym contracts, client invoices and online coaching statements. Separate wages taxed through PAYE from genuine self-employed session fees. Where a gym collects payments and retains an amount, establish whether it is paying wages or settling your business receipts after charges.</p>\n<p>The contract wording alone may not settle employment status. Explain the practical arrangement if control, substitution or financial risk makes the position uncertain.</p>\n<h2>Track packages and refunds</h2>\n<p>A client may buy several sessions in advance, cancel or receive a refund. Keep records of the amount received, what was promised and any money returned. Your accounting method determines the relevant timing for the tax calculation.</p>\n<p>For example, a bank deposit for ten sessions should be traceable to that client&#x27;s agreement. It should not be entered again as new income every time a session is delivered without checking how the initial payment was recorded.</p>\n<h2>Business spending needs a business purpose</h2>\n<p>Gym rental, relevant insurance, booking charges and qualifying equipment may be allowable where the conditions are met. Ordinary sports clothing, personal gym use and personal food are not automatically deductible because you work in fitness.</p>\n<p>Training costs require particular care. Updating skills used in an existing business and obtaining skills for a new activity can have different tax treatment. Keep the course details and explain their connection to the work.</p>\n<h2>Give the accountant a complete picture</h2>\n<p>Supply platform statements, cash income records, contracts, receipts and employment information. If clients pay from abroad, tell the accountant rather than assuming the platform has dealt with all tax consequences.</p>\n<p>TaxSimba can confirm the appropriate personal tax service and required records. If you also sell products, run separate activities or approach MTD thresholds, raise those facts before the return is prepared so the scope matches how the business actually operates.</p>",
