    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>Living outside the UK does not automatically make UK rental income tax-free. The Non-resident Landlords Scheme can affect how rent is paid, while the annual tax return establishes the wider liability.</p>\n<h2>The scheme and tax residence are different tests</h2>\n<p>HMRC&#x27;s guidance treats a landlord living abroad for six months or more a year as a non-resident landlord for the scheme, even where the person is UK resident for tax purposes. Your residence status needs its own assessment; do not infer it solely from a flight itinerary or overseas address.</p>\n<p>Supply travel dates, living arrangements and other relevant facts if residence needs reviewing. Double tax agreements and entitlement to allowances can also matter.</p>\n<h2>Tax may be withheld before you receive rent</h2>\n<p>Letting agents, and in some cases tenants, must operate the scheme unless HMRC has authorised payment without deduction. Ask for statements and tax certificates showing rent, deductible costs used in the withholding calculation and tax paid over.</p>\n<p>For example, an agent&#x27;s net transfer can already reflect management charges and withheld tax. Recording only that deposit as rent can lose both the gross income and a credit for tax already deducted.</p>\n<h2>Gross-payment approval is not an exemption</h2>\n<p>Permission to receive rental income without deduction does not mean there is no UK tax to pay. The annual reporting and payment position still needs checking. The scheme&#x27;s quarterly withholding calculation is not necessarily the final calculation of your rental profit or liability.</p>\n<h2>Confirm the filing route and service scope</h2>\n<p>Non-residence can require supplementary information and suitable filing software. If you are also within MTD, the software and agent arrangements must support the actual circumstances; do not assume an ordinary resident-landlord process is sufficient.</p>\n<p>Ask TaxSimba to confirm acceptance and scope before purchasing support for a non-resident case. Provide ownership details, rental statements, withholding certificates and relevant foreign tax information. A clear review at the start helps distinguish the UK rental return from any residence, treaty or overseas filing advice needing separate specialist work.</p>",
    "wordCount": 336,
    "iconKey": "home",
    "contentType": "Practical guide",
    "readingMinutes": 2,
