    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>A credit in your Self Assessment account does not always mean a repayment has already been issued. Check whether a refund was requested, whether HMRC is checking it and whether any amount has been used against another liability.</p>\n<h2>Start with the return and account balance</h2>\n<p>Compare the submitted tax calculation with the statement of account. Payments on account, earlier payments, adjustments and outstanding charges can affect the amount available for repayment. The refund expected from one year&#x27;s calculation may differ from the final account credit.</p>\n<p>If the return includes CIS deductions or other tax credits, make sure the supporting figures and statements are correct. A refund should follow an accurate return, not a target amount someone has promised before reviewing the evidence.</p>\n<h2>Understand a pending status</h2>\n<p>HMRC says a repayment may show as pending in the online account. Security or other checks can delay issue. Use HMRC&#x27;s current guidance and reply-time checker rather than relying on a fixed payment date quoted in an advert or online discussion.</p>\n<p>Check bank details carefully and follow genuine requests for further information. Do not send the same repayment request repeatedly simply because the first has not completed; first establish what is happening to it.</p>\n<h2>Keep the relevant references</h2>\n<p>Retain the filing confirmation, date of the repayment request, bank details supplied, HMRC correspondence and details of any identity checks. If an accountant is helping, tell them about contact you have already had with HMRC so enquiries are coordinated.</p>\n<p>For example, a repayment reduced by an outstanding payment on account may be an account-allocation issue rather than an error in the tax return. Amending a correct return will not necessarily solve that problem.</p>\n<h2>Know who controls the payment</h2>\n<p>An accountant can explain the calculation and assist with an agreed enquiry, but HMRC controls the checks and release of a repayment. TaxSimba should not be understood to guarantee HMRC&#x27;s processing time.</p>\n<p>Ask whether repayment follow-up work is included in your engagement. Keep any separate fee clear, and use official channels if an unexpected message asks you to pay money or disclose card details to unlock a tax refund.</p>",
    "wordCount": 357,
