    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>A business loan affects cash flow differently from taxable profit. The money borrowed, the repayment of that borrowing and the interest charged should not all be entered as ordinary sales or expenses.</p>\n<h2>Borrowing is not normally trading income</h2>\n<p>A genuine loan brings an obligation to repay. Receiving the borrowed capital is not usually a customer sale, and repaying the capital is not usually a deductible business running cost. The purchase funded by the loan needs its own tax treatment.</p>\n<p>For example, borrowing £5,000 to buy equipment does not normally create £5,000 of sales. A later repayment does not automatically create another equipment deduction. Keep the loan and the asset purchase separately identifiable.</p>\n<h2>Interest and charges need a purpose check</h2>\n<p>Interest on qualifying business borrowing and certain finance charges can be allowable, subject to the relevant rules. Personal use or mixed use can restrict the claim. The label on the bank account does not establish how the borrowed money was actually used.</p>\n<p>Supply the agreement, interest schedule and evidence of where the funds went. Where a payment contains both capital and interest, the accountant needs the breakdown rather than treating the whole instalment as an expense.</p>\n<h2>Different finance arrangements can differ</h2>\n<p>Hire purchase, leasing, credit cards and ordinary loans can require different analysis. Residential landlord finance costs also have separate restrictions, so do not transfer sole trader loan treatment directly to a buy-to-let mortgage.</p>\n<p>If a lender writes off debt or the business closes before repayment, raise it with the accountant. Those events can create questions beyond the ordinary annual interest entry.</p>\n<h2>Reconcile the bank and accounts</h2>\n<p>Explain transfers from personal savings and repayments to yourself as well as bank borrowing. Owner&#x27;s funds are not automatically sales, and money withdrawn for living costs is not a business expense.</p>\n<p>TaxSimba can review finance entries within your agreed bookkeeping or tax-return service. Providing a clear capital-and-interest schedule helps the accountant avoid both overstating expenses and overlooking genuine costs, while keeping the balance owed to the lender distinct from the tax due to HMRC.</p>",
    "wordCount": 344,
    "iconKey": "pound",
