    "curated": true,
    "status": "draft",
    "editorialReference": 118,
    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>Some sole traders and partners still have transition profits to include in their 2025/26 tax calculation following basis period reform. These are separate from the ordinary profit calculation for the current tax year.</p>\n<h2>Why earlier profits can still matter</h2>\n<p>The 2023/24 transition rules moved affected businesses towards reporting profits on a tax-year basis. Where additional transition profits arose after relevant overlap relief, spreading could apply over five years ending in 2027/28.</p>\n<p>A business with a non-tax-year accounting date is more likely to need this checked. Not every sole trader has transition profits, and changing accountant does not create a new spreading period.</p>\n<h2>Recover the earlier calculation</h2>\n<p>Provide the 2023/24 computation, overlap relief used, 2024/25 return and a schedule of transition profit already taxed. Any election to bring amounts into charge earlier needs to be reflected in the remaining balance.</p>\n<p>For example, an accountant cannot reliably calculate the 2025/26 allocation from the latest bank statements alone. They need to know the original transition figure and what happened in the earlier returns.</p>\n<h2>Avoid applying the same percentage blindly</h2>\n<p>The default spreading approach does not mean the same amount is always included regardless of earlier elections or cessation. HMRC&#x27;s 2025/26 helpsheet explains when spreading still applies and when amounts have already been fully taxed.</p>\n<p>If the business has ceased, remaining transition profits can need different treatment. Tell the accountant about closures, incorporation or other significant changes before the return is finalised.</p>\n<h2>Keep the current profit calculation separate</h2>\n<p>Transition profit is not new cash earned in 2025/26. It can nevertheless affect the tax calculation alongside current profits and other income. That is one reason a bill may differ from a simple percentage of this year&#x27;s bank surplus.</p>\n<p>Ask TaxSimba to confirm whether reconstructing an incomplete transition calculation is included or requires additional work. A proper handover from the previous accountant can save time. Keep the final schedule with your tax records so the remaining amount can be checked consistently in later years.</p>",
