    "sources": [
      {
        "label": "HMRC / GOV.UK — office property",
        "url": "https://www.gov.uk/expenses-if-youre-self-employed/office-property"
      },
      {
        "label": "HMRC / GOV.UK — capital allowances",
        "url": "https://www.gov.uk/capital-allowances"
      },
      {
        "label": "HMRC / GOV.UK — simpler income tax cash basis",
        "url": "https://www.gov.uk/simpler-income-tax-cash-basis"
      }
    ],
    "curated": true,
    "status": "draft",
    "editorialReference": 120,
    "researchCheckedAt": "2026-10-20",
    "editorialStatus": "completed-editorial-draft",
    "content": "<p>Business equipment can qualify for tax relief, but the route depends on the item, your accounting method and how it is used. Buying through a business bank account does not automatically make the full cost deductible.</p>\n<h2>Identify what was purchased</h2>\n<p>Tools, computers and machinery may be treated differently from consumables, buildings or vehicles. Keep the invoice, purchase date, payment details and an explanation of the item&#x27;s role in the business.</p>\n<p>The amount paid is not always the amount eligible for relief. Personal use, financing arrangements and particular asset rules can change the calculation.</p>\n<h2>Cash basis and traditional accounting differ</h2>\n<p>Under cash basis, many qualifying equipment purchases can be dealt with as expenses, although exceptions apply, including particular rules for cars. Traditional accounting can require capital allowances rather than an ordinary deduction for the asset&#x27;s cost.</p>\n<p>Depreciation shown in accounts is not automatically the tax deduction. The accountant may need to add it back and calculate the appropriate capital allowance separately.</p>\n<h2>Business use needs evidence</h2>\n<p>For example, a laptop used partly for private purposes should not automatically receive a 100% business deduction. Explain how it is used and retain a reasonable basis for any business proportion. Do not choose an arbitrary percentage because another trader used it.</p>\n<p>If equipment was owned privately before entering the business, or purchased before trading began, flag that history. Its tax treatment may differ from a new asset bought solely for business after commencement.</p>\n<h2>Keep sales and replacements linked</h2>\n<p>Selling, trading in or ceasing to use an asset can affect the tax position. Provide details of proceeds and previous claims. Claiming for a replacement does not mean the earlier item&#x27;s disposal can be ignored.</p>\n<p>Where finance is involved, supply the agreement so the asset purchase, loan capital and interest are not all claimed as separate versions of the same cost.</p>\n<p>TaxSimba can establish the appropriate treatment within the agreed service after reviewing the method and evidence. Ask before making a purchase solely for tax reasons: relief can reduce a liability, but it does not turn an unnecessary item into free equipment.</p>",
